\begin{ex}%[7D1N3]
Viết $\left(\dfrac{1}{8}\right)^{2}$ thành luỹ thừa của ${\dfrac{1}{2}}$ 
\choice
{ $\left(\dfrac{1}{8} \right)^{2}= \left(\dfrac{1}{2}\right)^{5}$  }
   { $\left(\dfrac{1}{8} \right)^{2}= \left(\dfrac{1}{2}\right)^{4}$  }
     { \True  $\left(\dfrac{1}{8} \right)^{2}= \left(\dfrac{1}{2}\right)^{6}$ }
    {  $\left(\dfrac{1}{8} \right)^{2}= \left(\dfrac{1}{2}\right)^{7}$ }
\loigiai{
Áp dụng quy tắc lũy thừa của số hữu tỉ: $(a^m)^n = a^{m \cdot n}$, $a^m \cdot a^n = a^{m+n}$, $\dfrac{a^m}{a^n} = a^{m-n}$, đưa về cùng cơ số ta thu được: $\left(\dfrac{1}{8} \right)^{2}=  \left[\left(\dfrac{1}{2} \right)^{3} \right] ^{2}=\left(\dfrac{1}{2}\right)^{6}$.
}\end{ex}

